-- LOCAL / SYNTHETIC ONLY. Records protocol observations, never SEFAZ authorization.
-- No grants from 048/050/051 are extended. Bytes/XSD are verified by the private executor.
begin;
create schema erp_fiscal_reconciliation;
revoke all on schema erp_fiscal_reconciliation from public,anon,authenticated,service_role;
create table erp_fiscal_reconciliation.attempt(
 id uuid primary key,ordinal bigint generated always as identity unique,command_id uuid not null unique,actor uuid not null references auth.users(id),
 candidate_id uuid not null references erp_fiscal_signed.candidate(id),signed_hash text not null check(signed_hash~'^[a-f0-9]{64}$'),signed_size integer not null check(signed_size between 1 and 512000),
 access_key text not null,reference_digest text not null,model text not null check(model in('55','65')),issuer_cnpj text not null,
 identity_version integer not null check(identity_version>0),a1_version integer not null check(a1_version>0),credential_id uuid not null references erp_a1.credential(id),
 envelope_hash text not null references erp_a1.sealed_object(hash),certificate_fingerprint text not null,
 state text not null check(state in('prepared','dispatched','stored','failed_before_dispatch','uncertain')),
 lease_id uuid not null unique,nonce uuid not null unique,expires_at timestamptz not null,created_at timestamptz not null,used_at timestamptz,finished_at timestamptz,
 request_hash text check(request_hash~'^[a-f0-9]{64}$'),request_size integer check(request_size between 1 and 512000),error_code text,finalize_hash text,
 check((used_at is null)=(request_hash is null)),check((request_hash is null)=(request_size is null)),
 check((state in('prepared','dispatched'))=(finished_at is null)),check(state not in('prepared','failed_before_dispatch')or used_at is null),
 check(state not in('dispatched','stored','uncertain')or used_at is not null));
create table erp_fiscal_reconciliation.command(id uuid primary key,actor uuid not null references auth.users(id),request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),attempt_id uuid not null unique references erp_fiscal_reconciliation.attempt(id),receipt jsonb not null,created_at timestamptz not null);
create table erp_fiscal_reconciliation.artifact(attempt_id uuid primary key references erp_fiscal_reconciliation.attempt(id),response_hash text not null check(response_hash~'^[a-f0-9]{64}$'),size_bytes integer not null check(size_bytes between 1 and 512000),evidence jsonb not null,created_at timestamptz not null);
create table erp_fiscal_reconciliation.audit(id bigint generated always as identity primary key,attempt_id uuid not null references erp_fiscal_reconciliation.attempt(id),actor uuid not null references auth.users(id),action text not null check(action in('prepare','consume','store','fail')),created_at timestamptz not null default clock_timestamp(),unique(attempt_id,action));
alter table erp_fiscal_reconciliation.attempt enable row level security;
alter table erp_fiscal_reconciliation.command enable row level security;
alter table erp_fiscal_reconciliation.artifact enable row level security;
alter table erp_fiscal_reconciliation.audit enable row level security;
revoke all on all tables in schema erp_fiscal_reconciliation from public,anon,authenticated,service_role;
revoke all on all sequences in schema erp_fiscal_reconciliation from public,anon,authenticated,service_role;
alter default privileges in schema erp_fiscal_reconciliation revoke all on tables from public,anon,authenticated,service_role;
alter default privileges in schema erp_fiscal_reconciliation revoke all on functions from public,anon,authenticated,service_role;
create function erp_fiscal_reconciliation.immutable()returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception'reconciliation_history_immutable'using errcode='42501';end$$;
create trigger immutable_command before update or delete on erp_fiscal_reconciliation.command for each row execute function erp_fiscal_reconciliation.immutable();
create trigger immutable_artifact before update or delete on erp_fiscal_reconciliation.artifact for each row execute function erp_fiscal_reconciliation.immutable();
create trigger immutable_audit before update or delete on erp_fiscal_reconciliation.audit for each row execute function erp_fiscal_reconciliation.immutable();
create function erp_fiscal_reconciliation.guard_attempt()returns trigger language plpgsql set search_path=pg_catalog as $$begin
 if tg_op='DELETE'or old.state not in('prepared','dispatched','uncertain')or
 (to_jsonb(new)-array['state','used_at','finished_at','request_hash','request_size','error_code','finalize_hash'])is distinct from(to_jsonb(old)-array['state','used_at','finished_at','request_hash','request_size','error_code','finalize_hash'])then raise exception'reconciliation_attempt_immutable'using errcode='42501';end if;
 if old.state='prepared'and new.state='dispatched'then
  if new.used_at is null or new.used_at<old.created_at or new.used_at>=old.expires_at or new.request_hash is null or new.request_size is null or new.finished_at is not null or new.error_code is not null or new.finalize_hash is not null then raise exception'reconciliation_dispatch_conflict'using errcode='40001';end if;
 elsif(old.state='prepared'and new.state='failed_before_dispatch')or(old.state='dispatched'and new.state='uncertain')or(old.state in('dispatched','uncertain')and new.state='stored')then
  if new.used_at is distinct from old.used_at or new.request_hash is distinct from old.request_hash or new.request_size is distinct from old.request_size or new.finished_at is null or new.finalize_hash is null or(new.state='stored')<>(new.error_code is null)then raise exception'reconciliation_finish_conflict'using errcode='40001';end if;
 else raise exception'reconciliation_transition_invalid'using errcode='40001';end if;return new;end$$;
create trigger guard_attempt before update or delete on erp_fiscal_reconciliation.attempt for each row execute function erp_fiscal_reconciliation.guard_attempt();
create function erp_fiscal_reconciliation.flags()returns jsonb language sql immutable set search_path=pg_catalog as $$select jsonb_build_object(
 'data_mode','fiscal_reconciliation','profile','synthetic-protocol-reconciliation-v1','origin','synthetic','environment','2',
 'operation_authorized',false,'can_query',false,'can_emit',false,'can_transmit',false,'sefaz_authorized',false,'financial_mutation_performed',false,'stock_mutation_performed',false)$$;
-- Only immutable historical source bindings are required. No current commercial basis or signing A1 gate.
create function erp_fiscal_reconciliation.source(actor uuid,id uuid,tag text default null)returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare c erp_fiscal_signed.candidate;a erp_fiscal_signed.artifact;j erp_fiscal_unsigned.job;r erp_fiscal_numbering.reservation;i erp_fiscal_unsigned.identity;begin
 perform erp_a1.access(actor);select *into c from erp_fiscal_signed.candidate where candidate.id=source.id;
 if not found then raise exception'reconciliation_candidate_not_found'using errcode='P0002';end if;
 j:=erp_fiscal_signed.require_source(actor,c.unsigned_job_id);select *into r from erp_fiscal_numbering.reservation where reservation.id=j.reservation_id;select *into i from erp_fiscal_unsigned.identity where reservation_id=r.id;
 select *into a from erp_fiscal_signed.artifact where candidate_id=c.id;
 if c.state<>'stored'or a.candidate_id is null or i.reservation_id is null or(tag is not null and a.signed_hash<>tag) then raise exception'reconciliation_source_conflict'using errcode='40001';end if;
 perform erp_fiscal_signed.validate_evidence(a.evidence,c,a.signed_hash);
 return jsonb_build_object('candidate_id',c.id,'candidate_version',c.version,'unsigned_job_id',j.id,'reservation_id',r.id,'draft_id',j.draft_id,'model',r.model,'issuer_cnpj',r.issuer_cnpj,'access_key',i.access_key,'signed_hash',a.signed_hash,'signed_size',a.size_bytes,'reference_digest',a.evidence#>'{signature,reference_digest}','signing_a1_version',c.a1_version,'basis_hash',c.basis_hash,'completion_version',j.completion_version,'completion_hash',j.completion_hash);
end$$;
create function erp_fiscal_reconciliation.locks(actor uuid,command uuid)returns erp_a1.head language plpgsql set search_path=pg_catalog as $$declare h erp_a1.head;begin
 perform erp_a1.access(actor);perform pg_advisory_xact_lock(174852961,hashtext(command::text));perform pg_advisory_xact_lock(174852920,1);
 perform 1 from erp_access.membership where user_id=actor and active and role in('admin','fiscal')for share;if not found then raise exception'reconciliation_forbidden'using errcode='42501';end if;
 select *into h from erp_a1.head where singleton for share;return h;end$$;
create function erp_fiscal_reconciliation.context(a erp_fiscal_reconciliation.attempt)returns jsonb language sql stable set search_path=pg_catalog as $$select jsonb_build_object(
 'attempt_id',a.id,'command_id',a.command_id,'actor',a.actor,'lease_id',a.lease_id,'nonce',a.nonce,'expires_at',a.expires_at,
 'purpose','synthetic-protocol-reconciliation-v1','binding_profile','sp-protocol-soap12-reviewed-v1','environment','2','model',a.model,'method','POST',
 'endpoint',replace(erp_fiscal_wsdl.endpoint(a.model,'protocol'),'?WSDL',''),'identity_version',a.identity_version,'issuer_cnpj',a.issuer_cnpj,
 'a1_version',a.a1_version,'credential_id',a.credential_id,'envelope_hash',a.envelope_hash,'certificate_fingerprint',a.certificate_fingerprint,
 'candidate_id',a.candidate_id,'signed_hash',a.signed_hash,'signed_size',a.signed_size,'access_key',a.access_key,'reference_digest',a.reference_digest,
 'request_hash',a.request_hash,'request_size',a.request_size)$$;
create function erp_fiscal_reconciliation.check_a1(a erp_fiscal_reconciliation.attempt,h erp_a1.head)returns erp_a1.credential language plpgsql set search_path=pg_catalog as $$declare c erp_a1.credential;begin
 c:=erp_fiscal_wsdl.check_a1(h,a.identity_version,a.a1_version);
 if h.credential_id is distinct from a.credential_id or h.object_hash is distinct from a.envelope_hash or c.metadata->>'fingerprint_sha256'is distinct from a.certificate_fingerprint or c.context->>'holder_cnpj'is distinct from a.issuer_cnpj then raise exception'reconciliation_a1_conflict'using errcode='40001';end if;return c;end$$;
create function erp_fiscal_reconciliation.execution(a erp_fiscal_reconciliation.attempt,c erp_a1.credential)returns jsonb language sql stable set search_path=pg_catalog as $$select jsonb_build_object('private_executor_only',true,'context',erp_fiscal_reconciliation.context(a),'credential',jsonb_build_object('id',c.id,'context',c.context,'metadata',c.metadata,'object',jsonb_build_object('bucket','brufap-a1-vault','key','credentials/'||c.id::text||'/'||o.hash||'.json','hash',o.hash,'size_bytes',o.size_bytes,'key_id',o.key_id)))from erp_a1.sealed_object o where o.hash=a.envelope_hash and o.credential_id=c.id$$;
create function erp_fiscal_reconciliation.current(a erp_fiscal_reconciliation.attempt)returns jsonb language plpgsql stable set search_path=pg_catalog as $$declare co jsonb;h erp_a1.head;c erp_fiscal_signed.candidate;begin
 co:=erp_a1.company();select *into h from erp_a1.head where singleton;select *into c from erp_fiscal_signed.candidate where id=a.candidate_id;
 return jsonb_build_object('state',a.state,'identity_version',co->'identity_version','a1_version',h.version,'company_changed',co->'identity_version'is distinct from to_jsonb(a.identity_version)or co->>'cnpj'is distinct from a.issuer_cnpj,'a1_changed',h.version is distinct from a.a1_version or h.credential_id is distinct from a.credential_id or h.object_hash is distinct from a.envelope_hash,
 'grant_consumed',a.used_at is not null,'lease_expired',a.expires_at<=clock_timestamp(),'expires_at',a.expires_at,'used_at',a.used_at,'finished_at',a.finished_at,'recovery_required',a.state in('dispatched','uncertain'),'retry_transport_allowed',false,'candidate',erp_fiscal_signed.current(c));end$$;
create function erp_fiscal_reconciliation.view(a erp_fiscal_reconciliation.attempt)returns jsonb language sql stable set search_path=pg_catalog as $$select erp_fiscal_reconciliation.flags()||jsonb_build_object('command_id',a.command_id,'receipt',(select receipt from erp_fiscal_reconciliation.command where id=a.command_id),'current',erp_fiscal_reconciliation.current(a),'error_code',a.error_code,
 'artifact',(select jsonb_build_object('response_hash',response_hash,'size_bytes',size_bytes,'evidence',evidence,'created_at',created_at)from erp_fiscal_reconciliation.artifact where attempt_id=a.id),
 'recovery',jsonb_build_object('private_executor_only',true,'context',erp_fiscal_reconciliation.context(a)))$$;
create function public.erp_fiscal_reconciliation_begin(p_user_id uuid,p_command_id uuid,p_candidate_id uuid,p_signed_hash text,p_expected_identity_version integer,p_expected_a1_version integer,p_confirmed boolean)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare h erp_a1.head;c erp_a1.credential;a erp_fiscal_reconciliation.attempt;cmd erp_fiscal_reconciliation.command;s jsonb;tag text;at timestamptz;begin
 perform erp_a1.access(p_user_id);if p_command_id is null or p_candidate_id is null or p_signed_hash is null or p_signed_hash!~'^[a-f0-9]{64}$'or p_expected_identity_version is null or p_expected_identity_version<1 or p_expected_a1_version is null or p_expected_a1_version<1 or p_confirmed is distinct from true then raise exception'reconciliation_begin_invalid'using errcode='22023';end if;
 tag:=erp_fiscal_wsdl.hash(jsonb_build_object('actor',p_user_id,'candidate',p_candidate_id,'signed_hash',p_signed_hash,'identity_version',p_expected_identity_version,'a1_version',p_expected_a1_version,'confirmed',true,'profile','synthetic-protocol-reconciliation-v1'));
 h:=erp_fiscal_reconciliation.locks(p_user_id,p_command_id);s:=erp_fiscal_reconciliation.source(p_user_id,p_candidate_id,p_signed_hash);select *into cmd from erp_fiscal_reconciliation.command where id=p_command_id;
 if found then
  if cmd.actor<>p_user_id or cmd.request_hash<>tag then raise exception'reconciliation_command_conflict'using errcode='40001';end if;select *into a from erp_fiscal_reconciliation.attempt where id=cmd.attempt_id for update;
  if a.state<>'prepared'or a.expires_at<=clock_timestamp()then return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',true,'execution',null);end if;
  c:=erp_fiscal_reconciliation.check_a1(a,h);return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',true,'execution',erp_fiscal_reconciliation.execution(a,c));
 end if;
 c:=erp_fiscal_wsdl.check_a1(h,p_expected_identity_version,p_expected_a1_version);at:=clock_timestamp();
 if s->>'issuer_cnpj'is distinct from c.context->>'holder_cnpj'then raise exception'reconciliation_issuer_conflict'using errcode='40001';end if;
 insert into erp_fiscal_reconciliation.attempt(id,command_id,actor,candidate_id,signed_hash,signed_size,access_key,reference_digest,model,issuer_cnpj,identity_version,a1_version,credential_id,envelope_hash,certificate_fingerprint,state,lease_id,nonce,expires_at,created_at)
 values(gen_random_uuid(),p_command_id,p_user_id,p_candidate_id,p_signed_hash,(s->>'signed_size')::integer,s->>'access_key',s->>'reference_digest',s->>'model',s->>'issuer_cnpj',p_expected_identity_version,h.version,h.credential_id,h.object_hash,c.metadata->>'fingerprint_sha256','prepared',gen_random_uuid(),gen_random_uuid(),at+interval'60 seconds',at)returning *into a;
 insert into erp_fiscal_reconciliation.command(id,actor,request_hash,attempt_id,receipt,created_at)values(p_command_id,p_user_id,tag,a.id,(s-array['access_key','reference_digest','issuer_cnpj'])||jsonb_build_object('attempt_id',a.id,'ordinal',a.ordinal,'command_id',p_command_id,'profile','synthetic-protocol-reconciliation-v1','environment','2','identity_version',a.identity_version,'a1_version',a.a1_version,'confirmed',true,'created_at',at),at);
 insert into erp_fiscal_reconciliation.audit(attempt_id,actor,action)values(a.id,p_user_id,'prepare');
 if a.expires_at<=clock_timestamp()then raise exception'reconciliation_lease_expired'using errcode='40001';end if;
 return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',false,'execution',erp_fiscal_reconciliation.execution(a,c));end$$;
create function erp_fiscal_reconciliation.storage_check(a uuid,kind text,request_hash text,size integer)returns void language plpgsql set search_path=pg_catalog as $$begin
 if kind not in('requests','responses')or request_hash is null or request_hash!~'^[a-f0-9]{64}$'or size is null or size not between 1 and 512000 then raise exception'reconciliation_object_invalid'using errcode='22023';end if;
 if not exists(select 1 from pg_class where oid='storage.objects'::regclass and relrowsecurity)then raise exception'reconciliation_private_storage_required'using errcode='40001';end if;
 perform 1 from storage.buckets where id='brufap-fiscal-artifacts'and name='brufap-fiscal-artifacts'and public=false and file_size_limit=8388608 and allowed_mime_types=array['application/octet-stream']::text[]for share;
 if not found then raise exception'reconciliation_private_storage_required'using errcode='40001';end if;
 perform 1 from storage.objects where bucket_id='brufap-fiscal-artifacts'and name='reconciliation/'||a::text||'/'||kind||'/'||request_hash||'.xml'and metadata->>'size'=size::text and metadata->>'mimetype'='application/octet-stream'for share;
 if not found then raise exception'reconciliation_object_missing'using errcode='40001';end if;end$$;
create function public.erp_fiscal_reconciliation_use(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_request_hash text,p_request_size integer)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;h erp_a1.head;begin
 perform erp_a1.access(p_user_id);if p_attempt_id is null or p_lease_id is null or p_request_hash is null or p_request_hash!~'^[a-f0-9]{64}$'or p_request_size is null or p_request_size not between 1 and 512000 then raise exception'reconciliation_use_invalid'using errcode='22023';end if;
 select *into a from erp_fiscal_reconciliation.attempt where id=p_attempt_id;if not found then raise exception'reconciliation_not_found'using errcode='P0002';end if;
 h:=erp_fiscal_reconciliation.locks(p_user_id,a.command_id);perform erp_fiscal_reconciliation.source(p_user_id,a.candidate_id,a.signed_hash);select *into a from erp_fiscal_reconciliation.attempt where id=p_attempt_id for update;
 if a.actor<>p_user_id then raise exception'reconciliation_forbidden'using errcode='42501';end if;if a.lease_id<>p_lease_id or a.state<>'prepared'or a.expires_at<=clock_timestamp()then raise exception'reconciliation_use_conflict'using errcode='40001';end if;
 perform erp_fiscal_reconciliation.check_a1(a,h);perform erp_fiscal_reconciliation.storage_check(a.id,'requests',p_request_hash,p_request_size);
 update erp_fiscal_reconciliation.attempt set state='dispatched',used_at=clock_timestamp(),request_hash=p_request_hash,request_size=p_request_size where id=a.id returning *into a;insert into erp_fiscal_reconciliation.audit(attempt_id,actor,action)values(a.id,p_user_id,'consume');
 if a.expires_at<=clock_timestamp()then raise exception'reconciliation_lease_expired'using errcode='40001';end if;
 return erp_fiscal_reconciliation.flags()||jsonb_build_object('private_executor_only',true,'grant',erp_fiscal_reconciliation.context(a)||jsonb_build_object('issued_at',a.used_at));end$$;
create function erp_fiscal_reconciliation.validate_evidence(v jsonb,request_hash text,response_hash text)returns void language plpgsql immutable set search_path=pg_catalog as $$declare k text;p jsonb;begin
 if not erp_a1.exact(v,array['origin','request_hash','response_hash','payload_hash','binding_profile','schema_profile','validator_version','validator_hash','schema_manifest_hash','outcome','rejection_code','xsd_validated','context_matched','cstat','received_at','protocol','event_count','legacy_cancellation_observed','event_reconciliation_required','verified','tls_origin_verified','signature_verified','sefaz_authorized','can_emit','can_query','can_transmit'])or octet_length(v::text)>16384 then raise exception'reconciliation_evidence_invalid'using errcode='22023';end if;
 if v->>'origin'is distinct from'synthetic'or v->>'request_hash'is distinct from request_hash or v->>'response_hash'is distinct from response_hash or v->>'binding_profile'is distinct from'sp-protocol-soap12-reviewed-v1'or v->>'schema_profile'is distinct from'protocol-pl010d-v1.03'or v->>'validator_version'is distinct from'fiscal-protocol-runner-v1'or v->>'validator_hash'is distinct from'90f25cd7f3858b6af37294b075043f6d603c259f921307e3d5f6591cf249f735'or v->>'schema_manifest_hash'is distinct from'e49b6b35f34dc361f9a5611ac40e161fde7f2c23b32d3bc14b9a60d77c08f2ee' then raise exception'reconciliation_profile_invalid'using errcode='22023';end if;
 foreach k in array array['verified','tls_origin_verified','signature_verified','sefaz_authorized','can_emit','can_query','can_transmit']loop if v->k is distinct from'false'::jsonb then raise exception'reconciliation_trust_invalid'using errcode='22023';end if;end loop;
 if v->>'outcome'='rejected'then
  if v->'xsd_validated'is distinct from'false'::jsonb or v->'context_matched'is distinct from'false'::jsonb or jsonb_typeof(v->'rejection_code')is distinct from'string'or v->>'rejection_code'not in('SOAP_RESPONSE_REJECTED','XML_SIZE_OR_TYPE_INVALID','XML_ENCODING_INVALID','XML_DECLARATION_UNSUPPORTED','XML_MALFORMED','XML_QUERY_ROOT_INVALID','XML_TREE_LIMIT','XML_XSD_INVALID','XML_HOMOLOGATION_REQUIRED','XML_QUERY_KEY_MISMATCH','XML_QUERY_UF_MISMATCH','XML_QUERY_TIMESTAMP_INVALID','XML_PROTOCOL_CONTEXT_MISMATCH','XML_PROTOCOL_TIMESTAMP_INVALID','XML_PROTOCOL_DIGEST_INVALID','XML_AUTHORIZATION_PROTOCOL_INCOMPLETE','XML_PROTOCOL_DIGEST_MISMATCH','XML_EVENT_CONTEXT_MISMATCH')then raise exception'reconciliation_rejection_invalid'using errcode='22023';end if;
  foreach k in array array['cstat','received_at','protocol','event_count','legacy_cancellation_observed','event_reconciliation_required']loop if v->k is distinct from'null'::jsonb then raise exception'reconciliation_rejection_invalid'using errcode='22023';end if;end loop;
  if v->'payload_hash'<>'null'::jsonb and(jsonb_typeof(v->'payload_hash')<>'string'or v->>'payload_hash'!~'^[a-f0-9]{64}$')then raise exception'reconciliation_payload_invalid'using errcode='22023';end if;
 elsif v->>'outcome'='validated'then
  if v->'rejection_code'is distinct from'null'::jsonb or v->'xsd_validated'is distinct from'true'::jsonb or v->'context_matched'is distinct from'true'::jsonb or jsonb_typeof(v->'payload_hash')is distinct from'string'or v->>'payload_hash'!~'^[a-f0-9]{64}$'or jsonb_typeof(v->'cstat')is distinct from'string'or v->>'cstat'!~'^[0-9]{3,4}$'or not erp_a1.iso(v->'received_at')or jsonb_typeof(v->'event_count')is distinct from'number'or v->>'event_count'!~'^[0-9]+$'or(v->>'event_count')::numeric>25000 or jsonb_typeof(v->'legacy_cancellation_observed')is distinct from'boolean'or v->'event_reconciliation_required'is distinct from to_jsonb((v->>'event_count')::integer>0 or(v->>'legacy_cancellation_observed')::boolean or v->>'cstat'in('101','151'))then raise exception'reconciliation_observation_invalid'using errcode='22023';end if;
  p:=v->'protocol';if p<>'null'::jsonb then
   if not erp_a1.exact(p,array['cstat','number','received_at','reference_digest_matched'])or jsonb_typeof(p->'cstat')is distinct from'string'or p->>'cstat'!~'^[0-9]{3,4}$'or not erp_a1.iso(p->'received_at')or p->'reference_digest_matched'is distinct from'true'::jsonb or(p->'number'<>'null'::jsonb and(jsonb_typeof(p->'number')<>'string'or p->>'number'!~'^([0-9]{15}|[0-9]{17})$'))or(p->>'cstat'in('100','150')and(p->'number'='null'::jsonb or p->>'number'~'^0+$'))then raise exception'reconciliation_protocol_invalid'using errcode='22023';end if;
  elsif v->>'cstat'in('100','150')then raise exception'reconciliation_protocol_missing'using errcode='22023';end if;
 else raise exception'reconciliation_outcome_invalid'using errcode='22023';end if;end$$;
create function public.erp_fiscal_reconciliation_finish(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_response_hash text,p_response_size integer,p_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;tag text;begin
 perform erp_a1.access(p_user_id);if p_attempt_id is null or p_lease_id is null or p_response_hash is null or p_response_hash!~'^[a-f0-9]{64}$'or p_response_size is null or p_response_size not between 1 and 512000 then raise exception'reconciliation_finish_invalid'using errcode='22023';end if;
 select *into a from erp_fiscal_reconciliation.attempt where id=p_attempt_id;if not found then raise exception'reconciliation_not_found'using errcode='P0002';end if;
 perform erp_fiscal_reconciliation.locks(p_user_id,a.command_id);perform erp_fiscal_reconciliation.source(p_user_id,a.candidate_id,a.signed_hash);select *into a from erp_fiscal_reconciliation.attempt where id=p_attempt_id for update;
 if a.actor<>p_user_id then raise exception'reconciliation_forbidden'using errcode='42501';end if;
 if a.lease_id<>p_lease_id or a.used_at is null or a.state not in('dispatched','uncertain','stored')then raise exception'reconciliation_finish_conflict'using errcode='40001';end if;
 perform erp_fiscal_reconciliation.validate_evidence(p_evidence,a.request_hash,p_response_hash);tag:=erp_fiscal_wsdl.hash(jsonb_build_object('response_hash',p_response_hash,'size',p_response_size,'evidence',p_evidence));
 if a.state='stored'then if a.finalize_hash<>tag then raise exception'reconciliation_finish_conflict'using errcode='40001';end if;return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',true);end if;
 -- Recovery never touches a credential: expired lease or changed A1 cannot erase already received evidence.
 perform erp_fiscal_reconciliation.storage_check(a.id,'requests',a.request_hash,a.request_size);perform erp_fiscal_reconciliation.storage_check(a.id,'responses',a.request_hash,p_response_size);
 insert into erp_fiscal_reconciliation.artifact(attempt_id,response_hash,size_bytes,evidence,created_at)values(a.id,p_response_hash,p_response_size,p_evidence,clock_timestamp());
 update erp_fiscal_reconciliation.attempt set state='stored',finished_at=clock_timestamp(),error_code=null,finalize_hash=tag where id=a.id returning *into a;insert into erp_fiscal_reconciliation.audit(attempt_id,actor,action)values(a.id,p_user_id,'store');return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',false);end$$;
create function public.erp_fiscal_reconciliation_fail(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_error_code text)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;tag text;begin
 perform erp_a1.access(p_user_id);if p_attempt_id is null or p_lease_id is null or p_error_code is null or p_error_code not in('PREPARATION_FAILED','REQUEST_INVALID','TRANSPORT_UNCONFIRMED','JOURNAL_UNAVAILABLE','VALIDATOR_UNAVAILABLE')then raise exception'reconciliation_failure_invalid'using errcode='22023';end if;
 select *into a from erp_fiscal_reconciliation.attempt where id=p_attempt_id;if not found then raise exception'reconciliation_not_found'using errcode='P0002';end if;perform erp_fiscal_reconciliation.locks(p_user_id,a.command_id);perform erp_fiscal_reconciliation.source(p_user_id,a.candidate_id,a.signed_hash);select *into a from erp_fiscal_reconciliation.attempt where id=p_attempt_id for update;
 if a.actor<>p_user_id then raise exception'reconciliation_forbidden'using errcode='42501';end if;if a.lease_id<>p_lease_id then raise exception'reconciliation_failure_conflict'using errcode='40001';end if;
 tag:=erp_fiscal_wsdl.hash(jsonb_build_object('error_code',p_error_code));if a.state in('stored','failed_before_dispatch','uncertain')then return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',true);end if;
 update erp_fiscal_reconciliation.attempt set state=case when used_at is null then'failed_before_dispatch'else'uncertain'end,finished_at=clock_timestamp(),error_code=p_error_code,finalize_hash=tag where id=a.id returning *into a;insert into erp_fiscal_reconciliation.audit(attempt_id,actor,action)values(a.id,p_user_id,'fail');return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',false);end$$;
create function public.erp_fiscal_reconciliation_command(p_user_id uuid,p_command_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;begin
 perform erp_a1.access(p_user_id);select *into a from erp_fiscal_reconciliation.attempt where command_id=p_command_id;if not found then raise exception'reconciliation_not_found'using errcode='P0002';end if;if a.actor<>p_user_id then raise exception'reconciliation_forbidden'using errcode='42501';end if;perform erp_fiscal_reconciliation.source(p_user_id,a.candidate_id,a.signed_hash);return erp_fiscal_reconciliation.view(a)||jsonb_build_object('read_only',true);end$$;
create function public.erp_fiscal_reconciliation_history(p_user_id uuid,p_candidate_id uuid,p_limit integer default 25,p_before bigint default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$declare items jsonb;more boolean;begin
 perform erp_fiscal_reconciliation.source(p_user_id,p_candidate_id);if p_limit is null or p_limit not between 1 and 25 or(p_before is not null and p_before<1)then raise exception'reconciliation_page_invalid'using errcode='22023';end if;
 select coalesce(jsonb_agg((erp_fiscal_reconciliation.view(a)-'recovery')order by a.ordinal desc),'[]'::jsonb)into items from(select *from erp_fiscal_reconciliation.attempt where candidate_id=p_candidate_id and(p_before is null or ordinal<p_before)order by ordinal desc limit p_limit)a;
 more:=jsonb_array_length(items)=p_limit and exists(select 1 from erp_fiscal_reconciliation.attempt where candidate_id=p_candidate_id and ordinal<(items->-1#>>'{receipt,ordinal}')::bigint);
 return erp_fiscal_reconciliation.flags()||jsonb_build_object('read_only',true,'candidate_id',p_candidate_id,'items',items,'limit',p_limit,'has_more',more,'next_cursor',case when more then items->-1#>>'{receipt,ordinal}'else null end);end$$;
revoke all on all functions in schema erp_fiscal_reconciliation from public,anon,authenticated,service_role;
revoke all on function public.erp_fiscal_reconciliation_begin(uuid,uuid,uuid,text,integer,integer,boolean),public.erp_fiscal_reconciliation_use(uuid,uuid,uuid,text,integer),public.erp_fiscal_reconciliation_finish(uuid,uuid,uuid,text,integer,jsonb),public.erp_fiscal_reconciliation_fail(uuid,uuid,uuid,text),public.erp_fiscal_reconciliation_command(uuid,uuid),public.erp_fiscal_reconciliation_history(uuid,uuid,integer,bigint)from public,anon,authenticated;
grant execute on function public.erp_fiscal_reconciliation_begin(uuid,uuid,uuid,text,integer,integer,boolean),public.erp_fiscal_reconciliation_use(uuid,uuid,uuid,text,integer),public.erp_fiscal_reconciliation_finish(uuid,uuid,uuid,text,integer,jsonb),public.erp_fiscal_reconciliation_fail(uuid,uuid,uuid,text),public.erp_fiscal_reconciliation_command(uuid,uuid),public.erp_fiscal_reconciliation_history(uuid,uuid,integer,bigint)to service_role;
commit;
